// Inverse NTT for Kyber (VLEN = 128) with Barrett multiplication, the counterpart of
// ntt_kyber_rvv_vlen128_barret_mul (ntt_kyber_rvv_vlen128_barret_mul.s). Input in the order of that
// NTT (= upstream's NTT order), output as upstream's invntt: multiplied by 2^16, |out| < q.
// Gentleman-Sande butterflies with plain inverse roots (include/intt_kyber_1234_567_twiddles_barret_mul.s,
// generated by examples/misc/gen_roots_riscv_ntt_dilithium.py).
// layer765:  8 blocks of 32 coefficients; levels 7, 6 (len 2, 4) on the block transposed in units of
// coefficient pairs (vlseg4e32), then level 5 (len 8).
// layer4321: 2 x 128 coefficients (as layer1234 of the NTT); levels 4, 3, 2 (len 16, 32, 64) and
// level 1 (len 128) merged with the scaling by 2^16 / 128. Level 1 uses the rounding
// Barrett multiplication (vsmul, vxrm = round-to-nearest-up), which yields centered
// results directly.
// Bounds (int16): as in aarch64/kyber/intt_kyber_123_4567.s, every coefficient is reduced once, after
// level 5 (Barrett multiplication by 1); the sums are not reduced otherwise. For an input with
// |a| <= 3071 (e.g. upstream's reduced basemul output, |a| <= q/2) the sums in layer765 stay below
// 8 * 3071 < 2^15, the reduction gives |a| <= 2003, the sums in layer4321 stay below 32048 < 2^15,
// and the outputs satisfy |out| < q.
// Uses only caller-saved scalar registers, so nothing is saved. Loop counter: t2.

    #define in        x10
    // == a0, first function arg
    #define root_ptr  x5
    #define modulus   x6
    #define barrett_v x16
    // round(2^15 / q), used by barrett_reduce

    #define data0  v0
    #define data1  v1
    #define data2  v2
    #define data3  v3
    #define data4  v4
    #define data5  v5
    #define data6  v6
    #define data7  v7
    #define data8  v8
    #define data9  v9
    #define data10 v10
    #define data11 v11
    #define data12 v12
    #define data13 v13
    #define data14 v14
    #define data15 v15

    #define vtmp0  v16
    // used by barret_mul, barrett_reduce
    #define vtmp1  v17
    // used by gs_butterfly, gs_butterfly_scale
    #define vtmp2  v18
    // used by gs_butterfly_scale

    // layer765: twiddles of one block
    #define vroot1      v19
    #define vbarretc_1  v20
    #define vroot2      v21
    #define vbarretc_2  v22
    #define vroot3      v23
    #define vbarretc_3  v24
    #define xroot1      x12
    #define xbarretc_1  x13
    #define xroot2      x14
    #define xbarretc_2  x15

    // layer4321: twiddles, loaded on demand
    #define xroot       x28
    #define xbarretc    x29
    #define xroot_f     x30
    #define xbarretc_f  x31

.macro barret_mul dst, a, b, barret_const
    vmul.vx \dst, \a, \b                            // z = a*b = coefficient (vect) * root (scalar)
    vmulh.vx vtmp0, \a, \barret_const               // t = (a * barret_const) >> 16
    vnmsac.vx \dst, modulus, vtmp0                  // z = z - n * t
.endm

.macro barret_mul_v vdst, va, vb, vbarret_const
    vmul.vv \vdst, \va, \vb                         // z = a*b = coefficient (vect) * root (vect)
    vmulh.vv vtmp0, \va, \vbarret_const             // t = (a * barret_const) >> 16
    vnmsac.vx \vdst, modulus, vtmp0                 // z = z - n * t
.endm

// as barret_mul, but with the rounded quotient round(a*b/q) instead of floor: the result is
// centered, |z| <= q/2 + q*|a|/2^16. barret_const_15 = round(b * 2^15 / q); needs vxrm = 0.
.macro barret_mul_round dst, a, b, barret_const_15
    vmul.vx \dst, \a, \b                            // z = a*b = coefficient (vect) * root (scalar)
    vsmul.vx vtmp0, \a, \barret_const_15            // t = round((a * barret_const_15) / 2^15)
    vnmsac.vx \dst, modulus, vtmp0                  // z = z - n * t
.endm

// barret_mul_round with b = 1 (the multiplication by 1 dropped): a = a - q * t with
// t = round(a * round(2^15 / q) / 2^15) ~ round(a / q), so |result| <= q/2 + 0.016 * |a|
// (2003 for |a| <= 8 * 3071, checked exhaustively). Needs vxrm = 0.
.macro barrett_reduce a
    vsmul.vx vtmp0, \a, barrett_v                   // t = round((a * round(2^15 / q)) / 2^15)
    vnmsac.vx \a, modulus, vtmp0                    // a = a - q * t
.endm

.macro gs_butterfly a, b, root, barret_const
    vsub.vv vtmp1, \a, \b                           // vtmp1 = a - b
    vadd.vv \a, \a, \b                              // a = a + b
    barret_mul \b, vtmp1, \root, \barret_const      // b = (a - b) * root mod modulus
.endm

.macro gs_butterfly_v va, vb, vroot, vbarret_const
    vsub.vv vtmp1, \va, \vb                         // vtmp1 = a - b
    vadd.vv \va, \va, \vb                           // a = a + b
    barret_mul_v \vb, vtmp1, \vroot, \vbarret_const // b = (a - b) * root mod modulus
.endm

// last level, merged with the final scaling: a = (a + b) * f, b = (a - b) * root * f, both
// with the rounding Barrett multiplication, so the outputs are centered (constants at 2^15 scale)
.macro gs_butterfly_scale a, b, root_f, barret_const_15, f, barret_const_f_15
    vadd.vv vtmp1, \a, \b                           // vtmp1 = a + b
    vsub.vv vtmp2, \a, \b                           // vtmp2 = a - b
    barret_mul_round \a, vtmp1, \f, \barret_const_f_15
    barret_mul_round \b, vtmp2, \root_f, \barret_const_15
.endm

// transpose in units of coefficient pairs (32 bit)
.macro transpose4 data, ptr
    vsetivli zero, 4, e32, m1
    vsseg4e32.v \data, (\ptr)   // @slothy:writes=["'transpose_buf'"]
    vl4re32.v   \data, (\ptr)   // @slothy:reads=["'transpose_buf'"]
    vsetivli zero, 8, e16, m1
.endm

.macro load16 in, stride
    vle16.v data0, (\in)
    addi \in, \in, \stride
    vle16.v data1, (\in)
    addi \in, \in, \stride
    vle16.v data2, (\in)
    addi \in, \in, \stride
    vle16.v data3, (\in)
    addi \in, \in, \stride
    vle16.v data4, (\in)
    addi \in, \in, \stride
    vle16.v data5, (\in)
    addi \in, \in, \stride
    vle16.v data6, (\in)
    addi \in, \in, \stride
    vle16.v data7, (\in)
    addi \in, \in, \stride
    vle16.v data8, (\in)
    addi \in, \in, \stride
    vle16.v data9, (\in)
    addi \in, \in, \stride
    vle16.v data10, (\in)
    addi \in, \in, \stride
    vle16.v data11, (\in)
    addi \in, \in, \stride
    vle16.v data12, (\in)
    addi \in, \in, \stride
    vle16.v data13, (\in)
    addi \in, \in, \stride
    vle16.v data14, (\in)
    addi \in, \in, \stride
    vle16.v data15, (\in)
.endm

.macro store16 in, stride
    vse16.v data0, (\in)
    addi \in, \in, \stride
    vse16.v data1, (\in)
    addi \in, \in, \stride
    vse16.v data2, (\in)
    addi \in, \in, \stride
    vse16.v data3, (\in)
    addi \in, \in, \stride
    vse16.v data4, (\in)
    addi \in, \in, \stride
    vse16.v data5, (\in)
    addi \in, \in, \stride
    vse16.v data6, (\in)
    addi \in, \in, \stride
    vse16.v data7, (\in)
    addi \in, \in, \stride
    vse16.v data8, (\in)
    addi \in, \in, \stride
    vse16.v data9, (\in)
    addi \in, \in, \stride
    vse16.v data10, (\in)
    addi \in, \in, \stride
    vse16.v data11, (\in)
    addi \in, \in, \stride
    vse16.v data12, (\in)
    addi \in, \in, \stride
    vse16.v data13, (\in)
    addi \in, \in, \stride
    vse16.v data14, (\in)
    addi \in, \in, \stride
    vse16.v data15, (\in)
.endm

